step(dt: number): boolean {
  const h = 1 / 240;
  const steps = Math.max(1, Math.min(16, Math.ceil(dt / h)));
  const s = dt / steps;
  for (let i = 0; i < steps; i++) {
    const a = this.k * (1 - this.x) - this.c * this.v;
    this.v += a * s;
    this.x += this.v * s;
  }
  return Math.abs(1 - this.x) < 0.001 && Math.abs(this.v) < 0.02;
}
